Peringatanif/else Hanya untuk SATU Nilai



if/else di R hanya mengecek satu kondisi (skalar). Untuk vektor, gunakan ifelse() atau case_when().
x &lt;- c(5, 15, 25)
if (x &gt; 10) { ... }    # Warning! Hanya elemen pertama yang dicek

__name__ == "__main__" Pattern
# src/analisis.py

def proses_data(filepath):
    import polars as pl
    df = pl.read_csv(filepath)
    return df.filter(pl.col("x") &gt; 0)

if __name__ == "__main__":
    # Hanya dijalankan jika file ini dieksekusi langsung
    result = proses_data("data/input.csv")

*args dan **kwargs
# *args — menerima argumen posisional tak terbatas
def total(*angka):
    return sum(angka)

total(1, 2, 3)       # 6
total(10, 20, 30, 40) # 100

# **kwargs — menerima keyword argument tak terbatas
def info(**data):
    return data

info(nama="Budi", umur=25)
# {'nama': 'Budi', 'umur': 25}

if / elif / else
x = 15

if x &gt; 10:
    hasil = "lebih dari 10"
else:
    hasil = "10 atau kurang"

hasil   # 'lebih dari 10'

if / elif / else
nilai = 75

if nilai &gt;= 85:
    grade = "A"
elif nilai &gt;= 70:
    grade = "B"
elif nilai &gt;= 55:
