tryCatch() — Menangkap Error
# Tangkap error, lanjut jalan
result &lt;- tryCatch(
  log("abc"),
  error = function(e) {
    NA    # return NA jika error
  }
)

result   # NA

# Tangkap warning juga
result &lt;- tryCatch(
  log(-1),
  warning = function(w) {
    NA
  }
)

try() — Versi Sederhana
result &lt;- try(log("abc"), silent = TRUE)
if (inherits(result, "try-error")) {
  result &lt;- NA
}

stop(), warning(), message()
# Di dalam fungsi sendiri
hitung_bmi &lt;- function(berat, tinggi) {
  if (tinggi &lt;= 0) stop("Tinggi harus positif!")
  if (berat &lt;= 0) stop("Berat harus positif!")
  if (tinggi &gt; 3) warning("Tinggi &gt; 3m — yakin dalam meter?")

  berat / tinggi^2
}

hitung_bmi(70, 1.75)    # 22.86
hitung_bmi(70, 0)       # Error: Tinggi harus positif!
hitung_bmi(70, 175)     # Warning + result

Step 3 — Cleaning
penjualan_clean &lt;- penjualan |&gt;
  # Isi diskon NA dengan 0

  mutate(diskon = replace_na(diskon, 0)) |&gt;
  # Hitung total
  mutate(
    total = jumlah * harga * (1 - diskon),
    bulan = month(tanggal, label = TRUE),
    kuartal = quarter(tanggal)
  ) |&gt;
  # Filter: hanya transaksi valid

  filter(total &gt; 0)

Step 4 — Analisis
# Revenue per kota
revenue_kota &lt;- penjualan_clean |&gt;
  summarise(
    total_revenue = sum(total),
    n_transaksi = n(),
    avg_transaksi = mean(total),
    .by = kota
  ) |&gt;
  arrange(desc(total_revenue))

# Revenue per bulan
revenue_bulan &lt;- penjualan_clean |&gt;
  summarise(
    total_revenue = sum(total),
    .by = bulan
  )

# Produk terlaris
produk_terlaris &lt;- penjualan_clean |&gt;
  summarise(
    total_terjual = sum(jumlah),
    total_revenue = sum(total),
    .by = produk
  ) |&gt;
  arrange(desc(total_terjual))

forvalues — Loop Angka
forvalues i = 1/5 {
    display `i'
}
// 1 2 3 4 5

Variasi Syntax
* Increment
forvalues i = 0(10)50 {
    display `i'
}
// 0 10 20 30 40 50

* Countdown
forvalues i = 5(-1)1 {
    display `i'
}
// 5 4 3 2 1

foreach — Loop Over List

List Item
foreach kota in Jakarta Bandung Surabaya {
    display "`kota'"
}


Variable List
sysuse auto, clear

foreach var of varlist price mpg weight {
    summarize `var'
}


Macro List
local negara "Indonesia Malaysia Thailand Vietnam"

foreach n of local negara {
    display "`n'"
}


Numlist
foreach x of numlist 1 3 5 7 9 {
    display `x'^2
}
// 1 9 25 49 81






